create extension if not exists pgcrypto;
create table if not exists public.products(id uuid primary key default gen_random_uuid(),name text not null,slug text unique,description text not null default '',category text not null default 'Other',price numeric(10,2) not null default 0 check(price>=0),compare_at_price numeric(10,2),image_url text not null default '',badge text,featured boolean not null default false,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.admin_users(user_id uuid primary key references auth.users(id) on delete cascade,created_at timestamptz not null default now());
alter table public.products enable row level security; alter table public.admin_users enable row level security;
drop policy if exists "Anyone can read active products" on public.products; create policy "Anyone can read active products" on public.products for select to anon,authenticated using(active=true or exists(select 1 from public.admin_users a where a.user_id=(select auth.uid())));
drop policy if exists "Admins can insert products" on public.products; create policy "Admins can insert products" on public.products for insert to authenticated with check(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid())));
drop policy if exists "Admins can update products" on public.products; create policy "Admins can update products" on public.products for update to authenticated using(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid()))) with check(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid())));
drop policy if exists "Admins can delete products" on public.products; create policy "Admins can delete products" on public.products for delete to authenticated using(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid())));
drop policy if exists "Admins can read admin roster" on public.admin_users; create policy "Admins can read admin roster" on public.admin_users for select to authenticated using(user_id=(select auth.uid()));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('product-images','product-images',true,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do update set public=true,file_size_limit=5242880,allowed_mime_types=array['image/jpeg','image/png','image/webp'];
drop policy if exists "Public can view product images" on storage.objects; create policy "Public can view product images" on storage.objects for select using(bucket_id='product-images');
drop policy if exists "Admins can upload product images" on storage.objects; create policy "Admins can upload product images" on storage.objects for insert to authenticated with check(bucket_id='product-images' and exists(select 1 from public.admin_users a where a.user_id=(select auth.uid())));
drop policy if exists "Admins can update product images" on storage.objects; create policy "Admins can update product images" on storage.objects for update to authenticated using(bucket_id='product-images' and exists(select 1 from public.admin_users a where a.user_id=(select auth.uid()))) with check(bucket_id='product-images' and exists(select 1 from public.admin_users a where a.user_id=(select auth.uid())));
drop policy if exists "Admins can delete product images" on storage.objects; create policy "Admins can delete product images" on storage.objects for delete to authenticated using(bucket_id='product-images' and exists(select 1 from public.admin_users a where a.user_id=(select auth.uid())));
-- After creating an auth user, grant admin access: insert into public.admin_users(user_id) values('REAL_AUTH_USER_UUID');
